  public TextBuffer appendCastTypeName(String castName, VarType type) {
    if (type.type == CodeType.OBJECT) {
      if (type.arrayDim > 0) {
        String name = castName.substring(0, castName.length() - type.arrayDim * 2);
        appendAllClasses(name, type.value);
