   760	      String s = res.get(i);
   761	      if (s.trim().equals("{") || s.trim().equals("}")) {
   762	        res.set(i-1, res.get(i-1).concat(s));
   763	        res.remove(i);
   764	      }
   765	      if (res.size() <= requiredLineNumber) {
   766	        return res;
   767	      }
   768	    }
   769	    // now join empty lines
   770	    for (int i = res.size()-1; i > 0 ; i--) {
   771	      String s = res.get(i);
   772	      if (s.trim().isEmpty()) {
   773	        res.set(i-1, res.get(i-1).concat(s));
   774	        res.remove(i);
   775	      }
   776	      if (res.size() <= requiredLineNumber) {
   777	        return res;
   778	      }
   779	    }
   780	    return res;
