  private static final Map<String, String> SHORT_TO_LONG_NAME_MAP = new HashMap<>();

  private static final String[] CUSTOM_CHECKS = {
    "-e=",
    "--add-external=",
    "-only=",
    "--only=",
    "-s",
    "--silent"
